import React, { useEffect, useRef } from 'react';

const TechParticles = () => {
    const canvasRef = useRef(null);
    const mouse = useRef({ x: null, y: null, radius: 150 });

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d');
        const archImg = new Image();
        archImg.src = '/images/arch-linux.svg';

        const setupCanvas = () => {
            const dpr = window.devicePixelRatio || 1;
            canvas.width = canvas.clientWidth * dpr;
            canvas.height = canvas.clientHeight * dpr;
            ctx.scale(dpr, dpr);
        };

        setupCanvas();

        const particleCount = 120; // Increased count
        const logoCount = 15; // Increased count
        let particles = [];

        class Particle {
            constructor() {
                this.init();
            }
            init() {
                const w = canvas.width / (window.devicePixelRatio || 1);
                const h = canvas.height / (window.devicePixelRatio || 1);
                this.x = Math.random() * w;
                this.y = Math.random() * h;
                this.baseX = this.x; // Store initial position
                this.baseY = this.y;
                this.size = Math.random() * 2 + 1;
                this.speedX = Math.random() * 0.5 - 0.25;
                this.speedY = Math.random() * 0.5 - 0.25;
                this.density = (Math.random() * 30) + 1;
                this.color = `rgba(6, 182, 212, ${Math.random() * 0.3 + 0.2})`;
            }
            update() {
                // Movement logic
                this.x += this.speedX;
                this.y += this.speedY;

                // Mouse Repel Logic
                let dx = mouse.current.x - this.x;
                let dy = mouse.current.y - this.y;
                let distance = Math.sqrt(dx * dx + dy * dy);
                let forceDirectionX = dx / distance;
                let forceDirectionY = dy / distance;
                let maxDistance = mouse.current.radius;
                let force = (maxDistance - distance) / maxDistance;
                let directionX = forceDirectionX * force * this.density;
                let directionY = forceDirectionY * force * this.density;

                if (distance < mouse.current.radius) {
                    this.x -= directionX;
                    this.y -= directionY;
                }

                // Screen Wrap
                const w = canvas.width / (window.devicePixelRatio || 1);
                const h = canvas.height / (window.devicePixelRatio || 1);
                if (this.x > w) this.x = 0; else if (this.x < 0) this.x = w;
                if (this.y > h) this.y = 0; else if (this.y < 0) this.y = h;
            }
            draw() {
                ctx.fillStyle = this.color;
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
                ctx.fill();
            }
        }

        // Initialize particles
        for (let i = 0; i < particleCount; i++) particles.push(new Particle());

        const animate = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            particles.forEach(p => {
                p.update();
                p.draw();
            });
            requestAnimationFrame(animate);
        };

        animate();

        const handleMouseMove = (e) => {
            const rect = canvas.getBoundingClientRect();
            mouse.current.x = e.clientX - rect.left;
            mouse.current.y = e.clientY - rect.top;
        };

        const handleMouseOut = () => {
            mouse.current.x = null;
            mouse.current.y = null;
        };

        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseout', handleMouseOut);
        window.addEventListener('resize', setupCanvas);

        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseout', handleMouseOut);
            window.removeEventListener('resize', setupCanvas);
        };
    }, []);

    return <canvas ref={canvasRef} className="w-full h-full absolute top-0 left-0 pointer-events-none" />;
};

export default TechParticles;
